\title{Obstructions, Equivalences, and a Borel--Cantelli Heuristic\\ for Brocard's Problem}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
Brocard's problem asks for all pairs of natural numbers $(n, m)$ satisfying the
Diophantine equation $n! + 1 = m^2$. The only known solutions are $n = 4, 5, 7$,
the so-called \emph{Brown numbers}, and it is a famous open conjecture, due
independently to Brocard (1876) and Ramanujan (1913), that no others exist. This
paper assembles a multi-perspective, fully formalized treatment of the
surrounding theory. We prove a sharp non-square result for factorials themselves
($n!$ is a perfect square iff $n \le 1$) via Bertrand's postulate; we derive
structural obstructions on any solution (oddness of the root, the factorization
$(m-1)(m+1) = n!$, and a Wilson-theorem divisibility constraint forcing $m \ge p$
when $n = p-1$ is prime); we establish an exact geometric equivalence between
Brown numbers and triangular factorial-eighths through the identity
$8T_y + 1 = (2y+1)^2$; and we make the standard probabilistic finiteness
heuristic rigorous by proving convergence of $\sum_n 1/\sqrt{n!}$ and deriving an
abstract Borel--Cantelli theorem stating that, under the Brocard density model,
only finitely many factorial-plus-one values are squares almost surely. We
complement these structural results with an exhaustive, machine-checked
verification that no Brown numbers other than $4, 5, 7$ occur below $1000$. All
results are formally verified.
\end{abstract}

\section{Introduction}

\subsection{The problem}
For $n \in \mathbb{N}$ write $n! = \prod_{k=1}^{n} k$ for the factorial.
\textbf{Brocard's problem} is the determination of all solutions
$(n, m) \in \mathbb{N}^2$ of
\begin{equation}
n! + 1 = m^2. \tag{B}
\end{equation}
Direct computation reveals three solutions:
\[
4! + 1 = 25 = 5^2, \qquad 5! + 1 = 121 = 11^2, \qquad 7! + 1 = 5041 = 71^2.
\]
The corresponding values $n = 4, 5, 7$ are the \textbf{Brown numbers}. The
conjecture of Brocard and Ramanujan asserts these are the \emph{only} solutions;
it remains open despite extensive effort and verification past $n = 10^9$.

\subsection{Contributions}
This paper does not resolve the conjecture --- no elementary obstruction is
known --- but provides a structured body of rigorous, formally verified results
that illuminate it from four angles:
\begin{enumerate}
  \item A factorial non-square theorem (Section~\ref{sec:nonsquare}).
  \item Structural obstructions on any solution (Section~\ref{sec:obstructions}).
  \item A geometric equivalence with triangular numbers (Section~\ref{sec:geometry}).
  \item A rigorous Borel--Cantelli finiteness heuristic (Section~\ref{sec:bc}).
\end{enumerate}
A finite, exhaustive computational verification (Section~\ref{sec:computation})
confirms the absence of solutions below $1000$.

\section{Preliminaries and Definitions}
Throughout, $\mathbb{N} = \{0, 1, 2, \dots\}$ and $n!$ denotes the factorial.

\begin{definition}[Perfect square]
A natural number $m$ is a \emph{perfect square} if there exists $k \in \mathbb{N}$
with $m = k^2$.
\end{definition}

\begin{definition}[Triangular number]
A natural number $m$ is \emph{triangular} if $m = t(t+1)/2$ for some
$t \in \mathbb{N}$. The $y$-th triangular number is $T_y := y(y+1)/2$.
\end{definition}

\begin{definition}[Brown number]
A natural number $n$ is a \emph{Brown number} if there exists $m$ with
$n! + 1 = m^2$.
\end{definition}

\begin{definition}[Brocard density and detection predicate]
The \emph{Brocard density} of $n$ is $1/\sqrt{n!}$, the heuristic probability that
a number of magnitude $n!$ is a perfect square. The boolean detection predicate
used for exhaustive search is
$\mathrm{isPerfectSquareB}(N) := (\lfloor\sqrt{N}\rfloor^2 = N)$.
\end{definition}

We use three classical inputs: \textbf{Bertrand's postulate} (for $k \ge 1$ there
is a prime $p$ with $k < p \le 2k$), \textbf{Legendre's formula} for the $p$-adic
valuation of $n!$, and \textbf{Wilson's theorem}
($(p-1)! \equiv -1 \pmod p$ for $p$ prime).

\section{Factorials Are Almost Never Squares}\label{sec:nonsquare}

\begin{lemma}[Single-prime obstruction]
If $p$ is prime, $p \mid m$, and $p^2 \nmid m$, then $m$ is not a perfect square.
\end{lemma}
\begin{proof}
If $m = k^2$ then $p \mid k^2$, so by primality $p \mid k$, whence
$p^2 \mid k^2 = m$, contradicting $p^2 \nmid m$.
\end{proof}

\begin{lemma}[A prime dividing $n!$ exactly once]\label{lem:legendre}
If $p$ is prime with $p \le n < 2p$, then $p^2 \nmid n!$.
\end{lemma}
\begin{proof}
By Legendre's formula the exponent of $p$ in $n!$ is
$\sum_{i \ge 1} \lfloor n/p^i \rfloor$. Since $n < 2p \le p^2$, all terms with
$i \ge 2$ vanish, and $\lfloor n/p \rfloor = 1$ because $p \le n < 2p$. Thus the
exponent is exactly $1 < 2$, so $p^2 \nmid n!$.
\end{proof}

\begin{theorem}[\texttt{factorial\_not\_square\_of\_two\_le}]
For $n \ge 2$, $n!$ is not a perfect square.
\end{theorem}
\begin{proof}
Apply Bertrand's postulate to $k = \lfloor n/2 \rfloor \ge 1$: there is a prime
$p$ with $\lfloor n/2\rfloor < p \le n$. Then $p \le n$, so $p \mid n!$, and
$n < 2p$, so by Lemma~\ref{lem:legendre} $p^2 \nmid n!$. By the single-prime
obstruction, $n!$ is not a square.
\end{proof}

\begin{theorem}[\texttt{factorial\_square\_iff\_le\_one}]
$n!$ is a perfect square iff $n \le 1$.
\end{theorem}
\begin{proof}
If $n \le 1$ then $n! = 1 = 1^2$. Conversely, if $n \ge 2$, the previous theorem
forbids it.
\end{proof}

\begin{theorem}[\texttt{factorial\_square\_triangular\_iff\_le\_one}]
$n!$ is simultaneously a perfect square and a triangular number iff $n \le 1$.
\end{theorem}
\begin{proof}
The forward direction follows from the square classification. For $n \le 1$,
$n! = 1 = 1^2 = T_1$, which is both.
\end{proof}

The $+1$ shift in (B) destroys precisely the single-prime parity obstruction
powering these results, which is why (B) admits sporadic solutions.

\section{Structural Obstructions on Solutions of (B)}\label{sec:obstructions}

\begin{theorem}[\texttt{brocard\_m\_odd}]\label{thm:odd}
If $n \ge 2$ and $n! + 1 = m^2$, then $m$ is odd.
\end{theorem}
\begin{proof}
For $n \ge 2$, $2 \mid n!$, so $n! + 1$ is odd; hence $m^2$ is odd, forcing $m$
odd. (Formally one reduces modulo $4$: $n!$ is divisible by $4$ for $n \ge 4$, and
the cases $n = 2, 3$ are checked directly, so $m^2 \equiv 1 \pmod 4$.)
\end{proof}

\begin{theorem}[\texttt{brocard\_factor}]
If $m \ge 1$ and $n! + 1 = m^2$, then $(m-1)(m+1) = n!$.
\end{theorem}
\begin{proof}
From $n! = m^2 - 1$ and $m^2 - 1 = (m-1)(m+1)$.
\end{proof}

\begin{theorem}[Wilson obstruction, \texttt{brocard\_wilson\_dvd}]\label{thm:wilson}
If $p$ is prime and $(p-1)! + 1 = m^2$, then $p \mid m$.
\end{theorem}
\begin{proof}
By Wilson's theorem $(p-1)! \equiv -1 \pmod p$, so $p \mid (p-1)! + 1 = m^2$.
Since $p$ is prime, $p \mid m^2 \Rightarrow p \mid m$.
\end{proof}

\begin{corollary}[\texttt{brocard\_wilson\_ge}]
Under the hypotheses of Theorem~\ref{thm:wilson}, $m \ge p$.
\end{corollary}
\begin{proof}
$p \mid m$ and $m > 0$, so $m$ is a positive multiple of $p$, giving $m \ge p$.
\end{proof}

For $n = 4 = 5 - 1$ with $5$ prime the corollary predicts $5 \mid m$, and indeed
$m = 5$. For $n = 7$, since $8$ is composite, Wilson does not apply, and $m = 71$
is not divisible by $8$.

\section{The Geometric Equivalence via Triangular Numbers}\label{sec:geometry}

\begin{lemma}[\texttt{two\_mul\_triangular}]
$2 T_y = y(y+1)$ for all $y$.
\end{lemma}

\begin{lemma}[Octahedral identity, \texttt{eight\_triangular\_succ}]\label{lem:oct}
$8 T_y + 1 = (2y+1)^2$ for all $y$.
\end{lemma}
\begin{proof}
$8T_y = 4 \cdot 2T_y = 4y(y+1) = 4y^2 + 4y$, so
$8T_y + 1 = (2y+1)^2$.
\end{proof}

\begin{theorem}[Geometric equivalence, \texttt{factorial\_eq\_eight\_triangular\_iff\_brown}]
For $n \ge 2$, $n!/8$ is a triangular number if and only if $n! + 1$ is a perfect
square. In any solution the square root is $m = 2y + 1$, where $y$ is the
triangular index.
\end{theorem}
\begin{proof}
($\Rightarrow$) If $n!/8 = T_y$, then $n! = 8T_y$, so
$n! + 1 = (2y+1)^2$ by Lemma~\ref{lem:oct}.
($\Leftarrow$) If $n! + 1 = m^2$ then $m$ is odd (Theorem~\ref{thm:odd}), say
$m = 2y+1$; then $n! = (2y+1)^2 - 1 = 8T_y$, so $n!/8 = T_y$.
\end{proof}

\begin{theorem}[Explicit indices, \texttt{triangular\_indices}]
The Brown numbers correspond to triangular indices $y = 2, 5, 35$:
\[
\tfrac{4!}{8} = 3 = T_2,\quad \tfrac{5!}{8} = 15 = T_5,\quad \tfrac{7!}{8} = 630 = T_{35},
\]
with square roots $m = 5, 11, 71$ recovered as $2y+1$.
\end{theorem}

\begin{proposition}[\texttt{no\_triangular\_witness\_8\_to\_50}]
For $8 \le n \le 50$, $n!/8$ is not triangular. \qed
\end{proposition}

\section{A Rigorous Borel--Cantelli Heuristic}\label{sec:bc}

The perfect squares near $N$ are spaced $\approx 2\sqrt{N}$ apart, so a random
integer of size $N = n!$ is a square with probability of order $1/\sqrt{n!}$.

\begin{theorem}[Convergence, \texttt{summable\_inv\_sqrt\_factorial}]
The series $\displaystyle \sum_{n=0}^{\infty} 1/\sqrt{n!}$ converges.
\end{theorem}
\begin{proof}
By the ratio test, the ratio of consecutive terms is $1/\sqrt{n+1} \to 0$, so for
$n \ge 8$ it is at most $2/3 < 1$. Equivalently, $n! \ge 2^{n-1}$ gives
$1/\sqrt{n!} \le \sqrt{2}\,(\sqrt 2)^{-n}$.
\end{proof}

\begin{corollary}[\texttt{summable\_const\_div\_sqrt\_factorial}]
For any $C \in \mathbb{R}$, $\sum_n C/\sqrt{n!}$ converges.
\end{corollary}

\begin{lemma}[Finite total mass, \texttt{tsum\_ofReal\_heuristic\_ne\_top}]
For $C \ge 0$, $\sum_{n} \mathrm{ofReal}(C/\sqrt{n!}) \ne \infty$ in $[0, \infty]$.
\end{lemma}

\begin{theorem}[Brocard--Borel--Cantelli, \texttt{brocard\_heuristic\_finite}]\label{thm:bc}
Let $\mu$ be an outer measure on a space $\alpha$, and let $(E_n)_{n \in \mathbb{N}}$
model the events ``$n! + 1$ is a perfect square.'' Suppose there is $C \ge 0$ with
$\mu(E_n) \le \mathrm{ofReal}(C/\sqrt{n!})$ for all $n$. Then
\[
\mu\big(\{x : x \in E_n \text{ for infinitely many } n\}\big) = 0.
\]
\end{theorem}
\begin{proof}
By the density bound and monotonicity,
$\sum_n \mu(E_n) \le \sum_n \mathrm{ofReal}(C/\sqrt{n!}) < \infty$. The classical
Borel--Cantelli lemma then gives $\mu(\limsup_n E_n) = 0$.
\end{proof}

\begin{theorem}[Almost-sure finiteness, \texttt{brocard\_heuristic\_ae\_finite}]
Under the hypotheses of Theorem~\ref{thm:bc}, for $\mu$-almost every $x$ the set
$\{n : x \in E_n\}$ is finite.
\end{theorem}

These are \emph{unconditional} as abstract measure statements. They do not prove
Brocard's conjecture, since the modeling assumption $\mu(E_n) \lesssim 1/\sqrt{n!}$
is heuristic; but they establish that the probabilistic intuition is internally
consistent.

\section{Exhaustive Computational Verification}\label{sec:computation}

\begin{theorem}[\texttt{brocard\_no\_others\_below\_1000}]
The only Brown numbers $n < 1000$ are $4, 5, 7$. Equivalently, filtering
$\{0, \dots, 999\}$ by $\mathrm{isPerfectSquareB}(n! + 1)$ yields exactly
$[4, 5, 7]$.
\end{theorem}
\begin{proof}
Exhaustive evaluation of a decidable predicate. The integer square root is
computable in time logarithmic in the number of bignum multiplications, so the
test scales to $n!$ with thousands of digits ($999!$ has over $2500$ digits).
\end{proof}

\section{Discussion}
The four perspectives reinforce one another: the non-square theorem isolates which
mechanism the $+1$ shift breaks; the obstructions and the geometric equivalence
translate (B) into factorization and figurate-number language; the
Borel--Cantelli analysis explains why finiteness is expected; and the
verification grounds the picture in fact. The persistent gap is that none of these
tools bounds $n$: every obstruction is necessary, the heuristic is probabilistic,
and the search is finite.

\section{Future Directions}
\begin{itemize}
  \item General consecutive-factorial squares: classify when $n!\,(n+d)!$ is a
  perfect square (the $d=2$ case is the square case of Erd\H{o}s--Selfridge).
  \item Erd\H{o}s--Selfridge for short blocks: $a(a+1)\cdots(a+k-1)$ never square,
  for small fixed $k$.
  \item Strengthened residue sieve combining Wilson-type constraints across all
  primes $p \le n$ via CRT.
  \item Power variant $n! + 1 = m^k$ for $k \ge 3$, with a sharper sieve for odd $k$.
  \item Characterize the $n!\,m!$ perfect-square locus via squarefree parts of
  falling factorials.
\end{itemize}

\section{Conclusion}
We have presented a coherent, formally verified body of theory surrounding
Brocard's problem: a complete solution of the factorial non-square question, a
suite of structural obstructions, an exact geometric equivalence with triangular
numbers, a rigorous probabilistic finiteness heuristic, and an exhaustive
verification below $1000$. Together they delineate sharply both what is provable
and where the genuine difficulty resides.

\end{document}

